// BDA Module — Big Data Technologies premium question banks
const bigDataTechnologiesPremiumEasyQs=[{"q":"What does Big Data refer to?\n\nA.","o":["Data stored only in spreadsheets","Extremely large and complex datasets","Data containing only images","Data stored on a single computer"],"a":1,"e":"Big Data refers to datasets whose size, speed or complexity makes traditional data-processing methods insufficient."},{"q":"Which of the following is NOT one of the traditional 5 Vs of Big Data?\n\nA.","o":["Volume","Velocity","Variety","Visibility"],"a":3,"e":"The traditional 5 Vs are Volume, Velocity, Variety, Veracity and Value."},{"q":"Which technology is commonly used for distributed storage in Big Data?\n\nA.","o":["Hadoop HDFS","MS Paint","Notepad","Microsoft Word"],"a":0,"e":"HDFS stores large datasets across multiple machines in a distributed environment."},{"q":"What is the full form of HDFS?\n\nA.","o":["High Data File System","Hadoop Distributed File System","High Distributed Framework Service","Hadoop Data Formatting System"],"a":1,"e":"HDFS is Hadoop's distributed file system designed to store large datasets across multiple nodes."},{"q":"Which programming language is commonly associated with Hadoop MapReduce?\n\nA.","o":["HTML","CSS","Java","SQL only"],"a":2,"e":"Hadoop MapReduce is traditionally implemented using Java, although other languages can also interact with it."},{"q":"Which component is responsible for managing metadata in HDFS?\n\nA.","o":["DataNode","NameNode","ResourceManager","NodeManager"],"a":1,"e":"The NameNode maintains filesystem metadata, including file names, directory structure and block locations."},{"q":"What is the primary function of a DataNode?\n\nA.","o":["Store actual data blocks","Manage user authentication only","Compile Java programs","Schedule all cluster applications"],"a":0,"e":"DataNodes store and serve the actual data blocks in HDFS."},{"q":"What is the main purpose of Hadoop?\n\nA.","o":["Designing web pages","Editing images","Processing and storing large datasets","Creating mobile applications only"],"a":2,"e":"Hadoop provides distributed storage and processing capabilities for large datasets."},{"q":"Which of the following is a characteristic of Big Data?\n\nA.","o":["Small volume only","High volume","Fixed structure only","No processing requirement"],"a":1,"e":"Big Data often involves massive amounts of information generated from different sources."},{"q":"What does Velocity represent in Big Data?\n\nA.","o":["Speed of data generation and processing","Total storage capacity","Accuracy of stored data","Number of database tables"],"a":0,"e":"Velocity describes how quickly data is generated, collected and processed."},{"q":"Which of the following is an example of unstructured data?\n\nA.","o":["Relational database table","Excel table with fixed columns","JSON with a defined schema","Video file"],"a":3,"e":"Video files do not follow a fixed tabular structure and are considered unstructured data."},{"q":"What is the default storage unit used by HDFS for dividing files?\n\nA.","o":["Record","Block","Column","Row"],"a":1,"e":"HDFS divides large files into blocks and distributes them across DataNodes."},{"q":"Which Hadoop component manages cluster resources?\n\nA.","o":["ResourceManager","NameNode","DataNode","HiveServer2"],"a":0,"e":"YARN's ResourceManager manages and allocates resources across the Hadoop cluster."},{"q":"What does YARN stand for?\n\nA.","o":["Yet Another Resource Network","Young Application Resource Node","Yet Another Resource Negotiator","Hadoop Resource Notation"],"a":2,"e":"YARN is Hadoop's resource-management and job-scheduling framework."},{"q":"Which component executes tasks on individual worker nodes in YARN?\n\nA.","o":["NameNode","NodeManager","ResourceManager","Secondary NameNode"],"a":1,"e":"NodeManager manages containers and monitors resource usage on individual worker nodes."},{"q":"What are the two main phases of traditional MapReduce processing?\n\nA.","o":["Read and Write","Compile and Execute","Store and Retrieve","Map and Reduce"],"a":3,"e":"Map processes input records into intermediate key-value pairs, while Reduce processes grouped values."},{"q":"Which of the following is a distributed processing framework?\n\nA.","o":["Apache MapReduce","Microsoft Paint","Adobe Photoshop","Windows Notepad"],"a":0,"e":"MapReduce enables parallel processing of large datasets across multiple machines."},{"q":"What is Apache Hive primarily used for?\n\nA.","o":["Image processing","Data warehousing and SQL-like querying","Operating system management","Network routing"],"a":1,"e":"Hive provides a SQL-like query language called HiveQL for analyzing data stored in Hadoop."},{"q":"Which language is used to query data in Apache Hive?\n\nA.","o":["HTML","JavaScript","HiveQL","CSS"],"a":2,"e":"HiveQL is similar to SQL and is used to query and manage data in Hive."},{"q":"What is Apache Pig mainly used for?\n\nA.","o":["Creating operating systems","Managing computer hardware","Designing websites","Processing and analyzing large datasets"],"a":3,"e":"Apache Pig provides a high-level scripting platform for processing large datasets."},{"q":"Which scripting language is used by Apache Pig?\n\nA.","o":["Pig Latin","JavaScript","Python only","PL/SQL"],"a":0,"e":"Pig Latin is the data-flow scripting language used to write Apache Pig programs."},{"q":"Which of the following is a NoSQL database?\n\nA.","o":["MySQL","Oracle Database","HBase","Microsoft Access"],"a":2,"e":"HBase is a distributed, column-family-oriented NoSQL database built on top of HDFS."},{"q":"Apache Spark is primarily designed for:\n\nA.","o":["Word processing","Distributed data processing","Desktop publishing","Operating system installation"],"a":1,"e":"Spark is a distributed computing engine used for large-scale data processing and analytics."},{"q":"What does RDD stand for in Apache Spark?\n\nA.","o":["Random Data Distribution","Reliable Database Design","Remote Data Directory","Resilient Distributed Dataset"],"a":3,"e":"RDD is Spark's fundamental distributed data abstraction, designed to support fault-tolerant parallel processing."},{"q":"Which of the following is commonly used for real-time data streaming?\n\nA.","o":["Apache Kafka","Microsoft Word","Adobe Reader","Notepad"],"a":0,"e":"Apache Kafka is a distributed event-streaming platform used to collect, store and transmit data streams."},{"q":"Which of the following is an example of structured data?\n\nA.","o":["Audio recording","Relational database table","Video footage","Photograph"],"a":1,"e":"Structured data is organized into predefined fields, rows and columns."},{"q":"What does the term Volume represent in Big Data?\n\nA.","o":["Speed of processing","Accuracy of information","Amount of data","Type of data"],"a":2,"e":"Volume refers to the enormous quantity of data generated and stored."},{"q":"Which Hadoop component stores file system namespace information?\n\nA.","o":["DataNode","NodeManager","ApplicationMaster","NameNode"],"a":3,"e":"The NameNode maintains the HDFS namespace, including file and directory metadata."},{"q":"What happens when a DataNode fails in an HDFS cluster?\n\nA.","o":["HDFS can use replicated blocks from other DataNodes","All cluster data is immediately deleted","The NameNode becomes a DataNode","Hadoop permanently stops working"],"a":0,"e":"HDFS replication provides fault tolerance by maintaining copies of data blocks on multiple nodes."},{"q":"What is the default replication factor commonly configured in HDFS?\n\nA.","o":["1","3","5","10"],"a":1,"e":"The commonly used default HDFS replication factor is 3, though administrators can change it."},{"q":"Which component is responsible for monitoring DataNodes?\n\nA.","o":["Hive","Pig","NameNode","Kafka Producer"],"a":2,"e":"The NameNode receives heartbeats and block reports from DataNodes to monitor their status."},{"q":"What is the purpose of a heartbeat in HDFS?\n\nA.","o":["To transfer entire files","To delete unused blocks","To create new directories","To indicate that a DataNode is active"],"a":3,"e":"DataNodes periodically send heartbeats to the NameNode to report that they are functioning."},{"q":"Which of the following is a Hadoop ecosystem component?\n\nA.","o":["Hive","Photoshop","PowerPoint","CorelDRAW"],"a":0,"e":"Hive is part of the Hadoop ecosystem and supports querying and analyzing large datasets."},{"q":"Which tool is commonly used to transfer data between relational databases and Hadoop?\n\nA.","o":["HBase","Sqoop","Kafka Consumer","ZooKeeper"],"a":1,"e":"Apache Sqoop was designed to transfer bulk data between relational databases and Hadoop storage systems."},{"q":"Which tool is commonly used to collect and move log data into Hadoop?\n\nA.","o":["Pig","Hive","Flume","HBase"],"a":2,"e":"Apache Flume is a distributed service designed to collect, aggregate and move large amounts of log data."},{"q":"What is the main function of a Kafka Producer?\n\nA.","o":["Delete topics","Manage HDFS blocks","Execute SQL queries","Publish messages to Kafka topics"],"a":3,"e":"A Kafka Producer sends records or messages to Kafka topics."},{"q":"What is the main function of a Kafka Consumer?\n\nA.","o":["Read messages from Kafka topics","Create HDFS blocks","Compile MapReduce code","Allocate cluster memory"],"a":0,"e":"Consumers subscribe to Kafka topics and read the records published by producers."},{"q":"In Kafka, what is a topic?\n\nA.","o":["A storage device","A category or stream of messages","A programming language","A Hadoop server"],"a":1,"e":"A topic is a logical category in Kafka where related messages are published and consumed."},{"q":"Which of the following is a document-oriented NoSQL database?\n\nA.","o":["HDFS","Hive","MongoDB","YARN"],"a":2,"e":"MongoDB stores data in flexible document formats, commonly represented as BSON."},{"q":"Which data format is commonly used for semi-structured data?\n\nA.","o":["MP3","JPEG","WAV","JSON"],"a":3,"e":"JSON stores data as key-value pairs and nested structures, making it suitable for semi-structured data."},{"q":"Which of the following is an example of semi-structured data?\n\nA.","o":["XML document","Plain video file","Unformatted audio","Raw image pixels"],"a":0,"e":"XML uses tags and hierarchical organization without requiring a fixed relational table structure."},{"q":"Which component is responsible for running a MapReduce application's individual tasks?\n\nA.","o":["NameNode","Task execution containers","Hive Metastore","Kafka Broker"],"a":1,"e":"In Hadoop YARN, containers provide the resources in which application tasks execute."},{"q":"What is the output of the Map phase in MapReduce?\n\nA.","o":["Only text files","SQL tables","Intermediate key-value pairs","Database indexes"],"a":2,"e":"The Mapper generates intermediate key-value pairs that are grouped before being processed by Reducers."},{"q":"What is the primary purpose of the Shuffle and Sort phase?\n\nA.","o":["Compress all input files","Delete duplicate files","Create database tables","Group intermediate values by key"],"a":3,"e":"Shuffle and Sort transfers and groups mapper output so that each Reducer receives values associated with the same key."},{"q":"Which operation is performed by the Reducer?\n\nA.","o":["Aggregating or processing values associated with a key","Creating HDFS directories only","Managing network cables","Formatting hard disks"],"a":0,"e":"Reducers process grouped key-value data to generate final output."},{"q":"Which of the following is a common use of Big Data analytics?\n\nA.","o":["Changing screen brightness","Customer behavior analysis","Formatting documents","Installing device drivers"],"a":1,"e":"Businesses analyze large datasets to understand customer preferences and behavior."},{"q":"Which of the following is a key benefit of distributed computing?\n\nA.","o":["It requires only one computer","It eliminates all network communication","It enables parallel processing across multiple machines","It prevents data storage"],"a":2,"e":"Distributed computing divides workloads among multiple machines to improve processing capacity."},{"q":"What does fault tolerance mean in Big Data systems?\n\nA.","o":["Preventing all hardware failures","Removing all stored data","Stopping processing after an error","Continuing operation despite certain failures"],"a":3,"e":"Fault tolerance allows a system to recover from component failures without losing the ability to operate."},{"q":"Which of the following is used for cluster coordination in many Hadoop ecosystem deployments?\n\nA.","o":["Apache ZooKeeper","Microsoft Excel","Adobe Acrobat","Notepad++"],"a":0,"e":"Apache ZooKeeper provides coordination services such as configuration management and synchronization for distributed systems."},{"q":"Which of the following best describes horizontal scaling?\n\nA.","o":["Increasing the CPU speed of one machine","Adding more machines to a system","Increasing monitor resolution","Replacing the operating system"],"a":1,"e":"Horizontal scaling increases capacity by adding more nodes to a distributed system."},{"q":"Which of the following is a common Hadoop storage format?\n\nA.","o":["MP4","JPEG","SequenceFile","WAV"],"a":2,"e":"Hadoop SequenceFile is a binary file format that stores key-value pairs."},{"q":"What is the purpose of data replication in HDFS?\n\nA.","o":["To increase file size","To remove metadata","To reduce the number of nodes","To improve reliability and availability"],"a":3,"e":"Replication keeps multiple copies of data blocks so that data remains accessible if a node fails."},{"q":"Which of the following is an advantage of Apache Spark over traditional disk-based MapReduce for many workloads?\n\nA.","o":["In-memory processing","It requires no memory","It only supports text files","It works on a single machine only"],"a":0,"e":"Spark can cache data in memory, which can speed up iterative and interactive workloads."},{"q":"Which of the following is a Spark transformation?\n\nA.","o":["collect()","map()","count()","first()"],"a":1,"e":"map() transforms each element of a dataset and returns a new distributed dataset."},{"q":"Which of the following is a Spark action?\n\nA.","o":["filter()","flatMap()","collect()","map()"],"a":2,"e":"collect() is an action that returns the elements of a distributed dataset to the driver."},{"q":"What is lazy evaluation in Apache Spark?\n\nA.","o":["Executing all operations immediately","Disabling transformations","Storing data permanently in memory","Delaying execution until an action is called"],"a":3,"e":"Spark builds a logical execution plan for transformations and executes it when an action triggers computation."},{"q":"Which of the following is a Spark SQL feature?\n\nA.","o":["Querying structured data using SQL","Managing computer hardware","Creating operating system kernels","Designing graphical interfaces"],"a":0,"e":"Spark SQL enables structured data processing through SQL queries and DataFrame APIs."},{"q":"Which data abstraction is commonly used in modern Spark applications for structured data?\n\nA.","o":["HDFS block","DataFrame","DataNode","Kafka partition"],"a":1,"e":"A DataFrame represents distributed data organized into named columns, similar to a relational table."},{"q":"What is the primary role of a Kafka Broker?\n\nA.","o":["Compile Java source code","Execute SQL statements","Store and serve Kafka records","Manage HDFS metadata"],"a":2,"e":"Kafka brokers receive, store and deliver messages belonging to Kafka topics."},{"q":"What is a Kafka partition?\n\nA.","o":["A type of database query","A Hadoop resource manager","A programming variable","A subdivision of a topic"],"a":3,"e":"Kafka topics are divided into partitions to support parallel processing and scalability."},{"q":"Which of the following is a feature of NoSQL databases?\n\nA.","o":["Flexible data models","Mandatory fixed relational schemas","Only table-based storage","No support for distributed storage"],"a":0,"e":"Many NoSQL databases support flexible schemas and different data models."},{"q":"Which type of NoSQL database stores data as key-value pairs?\n\nA.","o":["Graph database","Key-value database","Relational database","Column-oriented SQL database"],"a":1,"e":"Key-value databases store each item as a key associated with a value."},{"q":"Which of the following is an example of a graph database?\n\nA.","o":["MySQL","Hive","Neo4j","HDFS"],"a":2,"e":"Neo4j stores data as nodes, relationships and properties, making it suitable for graph-based applications."},{"q":"What is the main purpose of the Hive Metastore?\n\nA.","o":["Store video files","Execute operating system commands","Manage Kafka partitions","Store metadata about Hive tables"],"a":3,"e":"Hive Metastore maintains metadata such as table schemas, columns, partitions and storage locations."},{"q":"Which command is used to display databases in Hive?\n\nA.","o":["SHOW DATABASES;","LIST DATABASES;","DISPLAY DATABASE;","GET DATABASES;"],"a":0,"e":"SHOW DATABASES; lists the databases available in Hive."},{"q":"Which command is commonly used to create a database in Hive?\n\nA.","o":["MAKE DATABASE","CREATE DATABASE","NEW DATABASE","ADD DATABASE"],"a":1,"e":"The Hive statement CREATE DATABASE database_name; creates a new database."},{"q":"Which clause is used to filter rows in a Hive query?\n\nA.","o":["ORDER BY","GROUP BY","WHERE","LIMIT"],"a":2,"e":"The WHERE clause filters rows according to a specified condition."},{"q":"Which clause is used to group records based on column values?\n\nA.","o":["DISTINCT","LIMIT","ORDER BY","GROUP BY"],"a":3,"e":"GROUP BY groups rows with matching values so aggregate functions can be applied."},{"q":"Which aggregate function calculates the number of rows?\n\nA.","o":["COUNT()","SUM()","AVG()","MAX()"],"a":0,"e":"COUNT() returns the number of rows or non-NULL values, depending on its argument."},{"q":"Which of the following is a common use of Apache HBase?\n\nA.","o":["Creating presentation slides","Storing and accessing large sparse datasets","Editing audio files","Managing desktop icons"],"a":1,"e":"HBase is designed for scalable, random real-time read and write access to large datasets."},{"q":"HBase is based on which data model?\n\nA.","o":["Relational table only","Graph model","Wide-column data model","Object-oriented model"],"a":2,"e":"HBase uses a wide-column data model organized around tables, rows, column families and cells."},{"q":"Which of the following is a major component of HBase architecture?\n\nA.","o":["ResourceManager","HiveServer","Kafka Producer","RegionServer"],"a":3,"e":"RegionServers manage regions and handle data read and write requests in HBase."},{"q":"What is the role of a RegionServer in HBase?\n\nA.","o":["Manage regions and handle client requests","Compile MapReduce programs","Store Hive query plans only","Schedule YARN applications"],"a":0,"e":"RegionServers serve data stored in HBase regions and handle read/write operations."},{"q":"Which of the following is commonly used to process streaming data?\n\nA.","o":["Microsoft Word","Apache Flink","Paint","PowerPoint"],"a":1,"e":"Apache Flink is a distributed processing framework designed for stateful stream processing and batch workloads."},{"q":"What is batch processing?\n\nA.","o":["Processing data one record at a time immediately","Processing only image files","Processing accumulated data in groups","Processing without input data"],"a":2,"e":"Batch processing collects data and processes it together at scheduled or triggered intervals."},{"q":"What is stream processing?\n\nA.","o":["Processing data only once a year","Processing data after manually saving files","Processing only static datasets","Processing continuously arriving data"],"a":3,"e":"Stream processing handles data continuously as events or records arrive."},{"q":"Which of the following is an example of a data source for Big Data systems?\n\nA.","o":["Social media platforms","Only printed books","Empty folders","Computer wallpapers"],"a":0,"e":"Social media platforms generate large volumes of text, images, videos and interaction data."},{"q":"What is data cleaning?\n\nA.","o":["Deleting all records","Identifying and correcting inaccurate or incomplete data","Encrypting every file","Compressing video files"],"a":1,"e":"Data cleaning improves data quality by handling missing values, duplicates and inconsistencies."},{"q":"What does Veracity mean in Big Data?\n\nA.","o":["Amount of data","Speed of data","Trustworthiness and quality of data","Variety of data formats"],"a":2,"e":"Veracity describes the reliability, accuracy and uncertainty of data."},{"q":"What does Variety refer to in Big Data?\n\nA.","o":["Processing speed","Data accuracy","Storage capacity","Different types and formats of data"],"a":3,"e":"Variety includes structured, semi-structured and unstructured data from multiple sources."},{"q":"Which of the following is a common application of Big Data in healthcare?\n\nA.","o":["Disease prediction and patient-data analysis","Changing computer wallpapers","Formatting text documents","Managing keyboard settings"],"a":0,"e":"Healthcare organizations use Big Data analytics to identify patterns and support diagnosis and treatment planning."},{"q":"Which of the following is a common application of Big Data in banking?\n\nA.","o":["Video editing","Fraud detection","Image compression","Desktop customization"],"a":1,"e":"Banks analyze transaction patterns to identify suspicious activities and potential fraud."},{"q":"Which of the following is a common challenge in Big Data?\n\nA.","o":["Lack of data sources everywhere","No need for storage","Data security and privacy","All data has the same format"],"a":2,"e":"Protecting sensitive information across distributed systems is a major Big Data challenge."},{"q":"Which of the following is used for distributed file storage in cloud environments?\n\nA.","o":["MS Paint","Calculator","Notepad","Amazon S3"],"a":3,"e":"Amazon S3 is an object storage service commonly used to store large datasets for analytics."},{"q":"What is the primary purpose of data partitioning?\n\nA.","o":["Dividing data into smaller parts","Removing all data","Converting data into images","Disabling parallel processing"],"a":0,"e":"Partitioning divides datasets into smaller logical or physical sections to improve data management and processing."},{"q":"Which of the following is a common file format used in Big Data analytics?\n\nA.","o":["BMP only","Apache Parquet","EXE","DLL"],"a":1,"e":"Apache Parquet is a columnar storage format optimized for analytical queries."},{"q":"What is the main advantage of columnar storage formats such as Parquet?\n\nA.","o":["They store only images","They cannot be compressed","Efficient analytical queries and compression","They require relational databases"],"a":2,"e":"Columnar formats allow queries to read only required columns and often provide effective compression."},{"q":"Which of the following is a common serialization format in Big Data systems?\n\nA.","o":["MP3","JPEG","PNG","Apache Avro"],"a":3,"e":"Apache Avro is a data serialization system that uses schemas to represent data."},{"q":"What is the function of a Combiner in Hadoop MapReduce?\n\nA.","o":["Perform local aggregation of mapper output","Replace the NameNode","Manage cluster authentication","Store all HDFS metadata"],"a":0,"e":"A Combiner can reduce the amount of intermediate data transferred across the network by performing local aggregation."},{"q":"Which of the following is true about a Hadoop cluster?\n\nA.","o":["It must contain exactly one computer","It consists of interconnected machines working together","It cannot store large files","It only supports desktop applications"],"a":1,"e":"A Hadoop cluster uses multiple connected machines for distributed storage and processing."},{"q":"What is the purpose of the Secondary NameNode in traditional HDFS architecture?\n\nA.","o":["Replace every DataNode","Execute all Reducer tasks","Periodically merge filesystem image and edit logs","Store every data block"],"a":2,"e":"The Secondary NameNode periodically creates checkpoints by merging the fsimage and edits log. It is not a standby NameNode."},{"q":"Which command is commonly used to list files in an HDFS directory?\n\nA.","o":["hadoop fs -delete","hadoop fs -format","hadoop fs -copy","hadoop fs -ls"],"a":3,"e":"hadoop fs -ls displays the contents of an HDFS directory."},{"q":"Which command is commonly used to copy a local file into HDFS?\n\nA.","o":["hadoop fs -put","hadoop fs -ls","hadoop fs -rm","hadoop fs -cat"],"a":0,"e":"The -put command uploads a file from the local filesystem to HDFS."},{"q":"Which command displays the contents of a file stored in HDFS?\n\nA.","o":["hadoop fs -mkdir","hadoop fs -cat","hadoop fs -rm","hadoop fs -touchz"],"a":1,"e":"The -cat command displays the contents of an HDFS file."},{"q":"Which of the following is a benefit of data compression?\n\nA.","o":["Increases unnecessary duplication","Removes data security","Reduces storage requirements","Prevents data processing"],"a":2,"e":"Compression reduces the amount of storage space required and can also reduce data transfer costs."},{"q":"Which of the following is a commonly used compression codec in Hadoop?\n\nA.","o":["JPEG","MP3","GIF","Snappy"],"a":3,"e":"Snappy is a compression codec commonly used in Hadoop and other data-processing systems."},{"q":"Which of the following best describes data ingestion?\n\nA.","o":["Collecting and importing data into a system","Deleting database tables","Formatting a hard disk","Creating computer networks"],"a":0,"e":"Data ingestion is the process of collecting data from different sources and bringing it into a storage or processing system."},{"q":"Which of the following is a common use of Apache ZooKeeper?\n\nA.","o":["Creating graphical user interfaces","Distributed coordination and synchronization","Editing documents","Performing image recognition only"],"a":1,"e":"ZooKeeper helps distributed applications coordinate configuration, synchronization and service discovery."},{"q":"Which of the following best describes Big Data analytics?\n\nA.","o":["Manually editing every data record","Storing files without analyzing them","Extracting useful insights and patterns from large datasets","Converting every file into a PDF"],"a":2,"e":"Big Data analytics uses computational methods to discover patterns, trends and useful information from large datasets."},{"q":"Which combination correctly represents the major capabilities of Hadoop?\n\nA. W","o":["Web designing and image editing","Audio recording and video playback","Desktop publishing and animation","Distributed storage and distributed processing"],"a":3,"e":"Hadoop provides distributed storage through HDFS and distributed resource management and processing through its ecosystem, including YARN and MapReduce."}];
const bigDataTechnologiesPremiumModerateQs=[{"q":"A company stores a 1 GB file in HDFS with a replication factor of 3. Approximately how much total storage is required for the file blocks?\n\nA.","o":["1 GB","2 GB","3 GB","4 GB"],"a":2,"e":"HDFS stores three copies of each block, so approximately 3 GB is required, excluding metadata and other overhead."},{"q":"Which HDFS component maintains the mapping between files and their data blocks?\n\nA.","o":["NameNode","DataNode","NodeManager","ResourceManager"],"a":0,"e":"The NameNode maintains filesystem metadata, including the locations of file blocks."},{"q":"A DataNode stops sending heartbeats to the NameNode. What is the likely consequence?\n\nA.","o":["The file is immediately deleted","The NameNode treats the DataNode as unavailable","The NameNode becomes a ResourceManager","All other DataNodes stop working"],"a":1,"e":"If heartbeats are not received within the configured interval, the NameNode marks the DataNode as dead and may initiate re-replication."},{"q":"What is the primary purpose of the HDFS Secondary NameNode?\n\nA.","o":["Store a second copy of every data block","Execute MapReduce tasks","Replace the active NameNode automatically","Create periodic checkpoints of filesystem metadata"],"a":3,"e":"The Secondary NameNode periodically merges the fsimage and edits log to create checkpoints. It is not a standby NameNode."},{"q":"Which stage in MapReduce groups values belonging to the same key?\n\nA.","o":["Input Splitting","Mapping","Shuffle and Sort","Output Writing"],"a":2,"e":"Shuffle and Sort transfers mapper output and groups intermediate values by key before reduction."},{"q":"Consider a word-count MapReduce job. What does the Mapper emit for the word cloud appearing once?\n\nA.","o":["(cloud, 1)","(1, cloud)","(cloud, cloud)","(1, 1)"],"a":0,"e":"A word-count mapper emits the word as the key and its occurrence count as the value."},{"q":"What is the primary benefit of using a Combiner in a word-count job?\n\nA.","o":["Increasing the number of input files","Reducing intermediate data transferred over the network","Replacing the Reducer completely","Increasing HDFS replication"],"a":1,"e":"A Combiner performs local aggregation on mapper output, reducing network traffic."},{"q":"Which statement about a MapReduce Reducer is correct?\n\nA.","o":["It always runs on the NameNode","It stores HDFS metadata","It receives ungrouped raw input files directly","It processes grouped intermediate values for each key"],"a":3,"e":"Reducers receive grouped key-value pairs after the shuffle and sort phase."},{"q":"In YARN, which component negotiates resources with the ResourceManager for an application?\n\nA.","o":["ApplicationMaster","DataNode","NameNode","Hive Metastore"],"a":0,"e":"The ApplicationMaster manages an application's execution and negotiates required containers with the ResourceManager."},{"q":"Which YARN component manages containers on an individual worker machine?\n\nA.","o":["ApplicationMaster","ResourceManager","NodeManager","Secondary NameNode"],"a":2,"e":"NodeManager launches and monitors containers and manages local resources on its node."},{"q":"What happens when a YARN application requests more containers than the cluster currently has available?\n\nA.","o":["The cluster deletes existing applications","The request may wait until resources become available","All DataNodes restart","The application is always executed immediately"],"a":1,"e":"ResourceManager scheduling depends on available resources, queue policies and application priorities."},{"q":"Which Hive feature allows data to be divided into logical sections based on column values?\n\nA.","o":["Bucketing","Indexing","Replication","Partitioning"],"a":3,"e":"Partitioning organizes Hive table data into separate directories based on partition-column values, which can improve query performance."},{"q":"A Hive table is partitioned by year. A query retrieves records only for 2025. What is the main advantage?\n\nA.","o":["Partition pruning can skip unrelated partitions","All partitions must be scanned","Hive automatically deletes older data","The table becomes a NoSQL database"],"a":0,"e":"Partition pruning allows Hive to scan only the relevant partition when the query filters on the partition column."},{"q":"What is bucketing in Hive?\n\nA.","o":["Dividing data into databases","Compressing every table into one file","Distributing records into a fixed number of files using a hash function","Replicating data across DataNodes"],"a":2,"e":"Bucketing distributes records into a predefined number of buckets based on the hash of a selected column."},{"q":"Which Hive command removes a table definition and its associated managed-table data?\n\nA.","o":["DELETE TABLE student;","DROP TABLE student;","REMOVE TABLE student;","CLEAR TABLE student;"],"a":1,"e":"Dropping a managed Hive table normally removes its metadata and underlying data. External-table data is generally retained."},{"q":"Which statement about an external Hive table is correct?\n\nA.","o":["It cannot contain partitions","It always deletes source data when dropped","It cannot query files in HDFS","Dropping it generally removes metadata but retains the underlying data"],"a":3,"e":"External tables reference data stored outside Hive's managed-table ownership."},{"q":"Which Pig Latin operator is used to filter records based on a condition?\n\nA.","o":["FILTER","GROUP","ORDER","STORE"],"a":0,"e":"FILTER selects tuples that satisfy a specified condition."},{"q":"Which Pig Latin operator combines two or more relations based on matching fields?\n\nA.","o":["LIMIT","DISTINCT","JOIN","FOREACH"],"a":2,"e":"JOIN combines relations using one or more matching fields."},{"q":"What is the purpose of the GROUP operator in Pig Latin?\n\nA.","o":["Remove all records","Group records based on a specified field","Create a Hive database","Sort files by their physical size"],"a":1,"e":"GROUP collects tuples with the same grouping key into a relation."},{"q":"Which of the following best describes HBase?\n\nA.","o":["A relational database that requires fixed SQL schemas","A batch-only processing engine","A programming language","A distributed wide-column NoSQL database"],"a":3,"e":"HBase provides distributed, scalable storage with random read/write access using a wide-column data model."},{"q":"In HBase, what uniquely identifies a row within a table?\n\nA.","o":["Row key","RegionServer name","Column family","Timestamp alone"],"a":0,"e":"Each HBase row is identified by its row key."},{"q":"Which HBase component is responsible for managing a set of regions?\n\nA.","o":["NameNode","ResourceManager","RegionServer","HiveServer2"],"a":2,"e":"RegionServers host and manage regions and handle client read/write requests."},{"q":"Which HBase data structure stores modifications before they are flushed to disk?\n\nA.","o":["HDFS NameNode","MemStore","Kafka partition","YARN container"],"a":1,"e":"MemStore holds recent writes in memory before they are flushed into HFiles."},{"q":"What is the main role of ZooKeeper in a traditional HBase deployment?\n\nA.","o":["Execute Hive queries","Store all HBase table data","Compile MapReduce programs","Coordinate distributed services and help manage cluster state"],"a":3,"e":"ZooKeeper supports coordination, service discovery and management of distributed HBase components."},{"q":"Which of the following is a Spark transformation?\n\nA.","o":["filter()","count()","collect()","saveAsTextFile()"],"a":0,"e":"filter() creates a new dataset containing elements that satisfy a specified condition."},{"q":"Which of the following is an action in Apache Spark?\n\nA.","o":["map()","filter()","reduce()","flatMap()"],"a":2,"e":"reduce() triggers computation and aggregates dataset elements using the specified function."},{"q":"What is the role of the Spark Driver?\n\nA.","o":["Store all HDFS blocks","Coordinate application execution and schedule tasks","Replace every worker node","Manage Kafka topics"],"a":1,"e":"The Driver coordinates the Spark application, builds execution plans and schedules tasks on executors."},{"q":"What is a Spark Executor?\n\nA.","o":["A Hive database","An HDFS metadata file","A Kafka message","A process that executes tasks and can store application data"],"a":3,"e":"Executors run tasks assigned by the Driver and can cache data during application execution."},{"q":"Which Spark component translates a logical execution plan into a physical execution plan for SQL queries?\n\nA.","o":["Catalyst Optimizer","NameNode","Kafka Broker","ZooKeeper"],"a":0,"e":"Spark SQL's Catalyst Optimizer analyzes and optimizes query plans before execution."},{"q":"What is the purpose of caching an RDD in Spark?\n\nA.","o":["Permanently store it in HDFS","Convert it into a Hive table","Reuse previously computed data without recomputing it","Delete intermediate records"],"a":2,"e":"Caching can speed up repeated operations by retaining computed partitions in memory or another configured storage level."},{"q":"Which Spark API is primarily designed for structured and semi-structured data processing?\n\nA.","o":["RDD only","DataFrame API","HDFS API","MapReduce API"],"a":1,"e":"DataFrames provide a structured representation of distributed data with named columns and support SQL optimizations."},{"q":"What does flatMap() do in Spark?\n\nA.","o":["Sorts all elements","Removes every duplicate","Counts records","Maps each input element to zero or more output elements and flattens the results"],"a":3,"e":"Unlike map(), which returns one output element per input element, flatMap() can return multiple elements."},{"q":"Which of the following is a narrow transformation in Spark?\n\nA.","o":["map()","groupByKey()","reduceByKey()","join()"],"a":0,"e":"A map() operation typically processes each partition independently without requiring a shuffle."},{"q":"Which Spark operation generally requires a shuffle?\n\nA.","o":["map()","filter()","groupByKey()","mapPartitions()"],"a":2,"e":"groupByKey() redistributes values so that all values for the same key are brought together."},{"q":"What is the purpose of checkpointing in Spark?\n\nA.","o":["Increase the number of input columns","Save data or computation state to reliable storage to truncate lineage","Delete all cached datasets","Replace the Spark Driver"],"a":1,"e":"Checkpointing saves an RDD or dataset to reliable storage and can shorten long dependency chains."},{"q":"Which of the following best describes Kafka's architecture?\n\nA.","o":["Centralized file storage only","A relational database architecture","A single-threaded desktop application","Distributed event-streaming architecture"],"a":3,"e":"Kafka distributes topics and partitions across brokers to provide scalability and fault tolerance."},{"q":"What is the purpose of a Kafka consumer group?\n\nA.","o":["Distribute topic partitions among multiple consumers","Combine multiple brokers into one file","Store HDFS metadata","Replace Kafka producers"],"a":0,"e":"Consumers in a group share the work of consuming partitions, allowing parallel processing."},{"q":"If a Kafka topic has four partitions and a consumer group has four active consumers, what is the maximum number of consumers that can actively consume one partition each at the same time?\n\nA.","o":["1","2","4","8"],"a":2,"e":"Within a consumer group, each partition is assigned to at most one consumer at a time, so four partitions can be consumed by four consumers in parallel."},{"q":"What does Kafka's replication factor control?\n\nA.","o":["Number of records per message","Number of copies of each partition maintained across brokers","Number of consumer groups","Size of a producer buffer"],"a":1,"e":"Replication factor determines how many replicas of each partition Kafka maintains."},{"q":"What is an offset in Kafka?\n\nA.","o":["The size of a broker","A topic name","A network address","A position identifier for a record within a partition"],"a":3,"e":"Kafka assigns offsets to records within each partition, enabling consumers to track their progress."},{"q":"Which Kafka setting controls how many acknowledgements a producer requires before considering a write successful?\n\nA.","o":["acks","group.id","auto.offset.reset","fetch.min.bytes"],"a":0,"e":"The acks producer setting controls the acknowledgement level required from Kafka brokers."},{"q":"Which statement about Kafka partitions is correct?\n\nA.","o":["All partitions must be stored on one broker","Partitions cannot be replicated","Partitions allow parallelism and distribution of data","Each partition must contain a different topic"],"a":2,"e":"Partitioning enables Kafka to distribute storage and processing across multiple brokers and consumers."},{"q":"Which of the following is a common data-ingestion tool for collecting log data?\n\nA.","o":["HBase","Apache Flume","Hive","Spark SQL"],"a":1,"e":"Flume is designed to collect, aggregate and transfer large volumes of event and log data."},{"q":"Which technology is designed for transferring bulk data between relational databases and Hadoop?\n\nA.","o":["ZooKeeper","Kafka","HBase","Sqoop"],"a":3,"e":"Sqoop supports bulk import and export between relational databases and Hadoop ecosystem storage."},{"q":"Which of the following is a key difference between Sqoop and Flume?\n\nA.","o":["Sqoop is commonly used for bulk structured data transfer, while Flume is used for event and log ingestion","Sqoop is a NoSQL database, while Flume is a programming language","Both are relational database servers","Flume manages HDFS metadata, while Sqoop manages YARN containers"],"a":0,"e":"Sqoop traditionally transfers bulk data from relational databases, while Flume collects and moves streaming event/log data."},{"q":"Which of the following is a columnar file format?\n\nA.","o":["CSV","XML","Parquet","Plain text"],"a":2,"e":"Parquet stores data by column, making it efficient for analytical workloads that read selected columns."},{"q":"Which of the following formats uses a row-oriented record structure and supports schema evolution?\n\nA.","o":["JPEG","Avro","MP3","PNG"],"a":1,"e":"Avro is a row-oriented serialization format that stores data with schema information and supports schema evolution."},{"q":"What is schema evolution?\n\nA.","o":["Deleting all table columns","Converting all data to text","Increasing the number of servers","Changing a data schema while maintaining compatibility with existing data"],"a":3,"e":"Schema evolution allows data structures to change over time while maintaining compatibility according to defined rules."},{"q":"Which of the following best describes a data lake?\n\nA.","o":["A centralized repository that can store raw data in various formats","A database that stores only numeric values","A system that stores only processed SQL tables","A tool for managing computer memory"],"a":0,"e":"A data lake stores raw and processed data in structured, semi-structured and unstructured formats."},{"q":"What is the main purpose of an ETL process?\n\nA.","o":["Encrypt, transfer and launch","Execute, test and load","Extract, transform and load data","Evaluate, track and link"],"a":2,"e":"ETL extracts data from sources, transforms it into a suitable format and loads it into a target system."},{"q":"Which of the following describes ELT?\n\nA.","o":["Extract, load and transform","Execute, load and test","Extract, link and transfer","Encrypt, load and transform"],"a":0,"e":"ELT loads extracted data into the target platform first and performs transformations afterward."},{"q":"Which of the following is a major advantage of distributed storage?\n\nA.","o":["It eliminates the need for networking","It enables storage across multiple machines","It prevents system scaling","It stores all data in one memory location"],"a":1,"e":"Distributed storage spreads data across multiple nodes, supporting scalability and fault tolerance."},{"q":"What is data locality in Hadoop?\n\nA.","o":["Storing data only on the NameNode","Sending every file to a central server","Processing data near where it is stored","Moving all data to the client computer"],"a":2,"e":"Data locality reduces network traffic by scheduling computation close to the data."},{"q":"Why does Hadoop prefer moving computation to data rather than moving large data to computation?\n\nA.","o":["To increase data duplication","To avoid using CPUs","To disable distributed processing","To reduce network transfer overhead"],"a":3,"e":"Processing data locally can reduce the amount of network traffic and improve overall performance."},{"q":"What is speculative execution in Hadoop MapReduce?\n\nA.","o":["Running duplicate copies of slow tasks to finish a job sooner","Deleting tasks that use memory","Executing every task on the NameNode","Repeating the entire cluster installation"],"a":0,"e":"Hadoop may launch another attempt of a slow-running task on a different node and use the result that finishes first."},{"q":"Which of the following can cause data skew in a MapReduce job?\n\nA.","o":["All keys having equal frequencies","One key receiving a disproportionately large number of records","Every mapper processing identical input sizes","A cluster having many DataNodes"],"a":1,"e":"Data skew occurs when data is unevenly distributed, causing some reducers to process much more data than others."},{"q":"Which technique can help reduce data skew in a distributed processing job?\n\nA.","o":["Increasing duplicate records","Disabling all reducers","Using salting to distribute hot keys","Removing all partitions"],"a":2,"e":"Salting adds additional key variation to distribute heavily concentrated keys across multiple processing tasks."},{"q":"What is the purpose of an InputFormat in Hadoop MapReduce?\n\nA.","o":["Manage DataNode failures","Allocate YARN containers","Compress the final output","Define how input data is split and read"],"a":3,"e":"InputFormat determines how input files are divided into input splits and how records are read."},{"q":"Which component converts input splits into key-value records for a Mapper?\n\nA.","o":["RecordReader","Reducer","ResourceManager","NameNode"],"a":0,"e":"RecordReader reads records from an input split and provides key-value pairs to the Mapper."},{"q":"What is the main purpose of OutputFormat in MapReduce?\n\nA.","o":["Create input splits","Define how final output is written","Schedule reducers","Store filesystem metadata"],"a":1,"e":"OutputFormat determines how the final key-value results are written to the output destination."},{"q":"Which of the following is true about HDFS block size?\n\nA.","o":["It must always be 1 KB","It cannot be configured","It is configurable and commonly much larger than traditional filesystem blocks","It is always equal to the file size"],"a":2,"e":"HDFS uses relatively large configurable blocks to support efficient distributed storage and processing."},{"q":"A file is smaller than the configured HDFS block size. What happens?\n\nA.","o":["It is automatically deleted","It is split into hundreds of blocks","It cannot be stored","It typically occupies one block, with unused capacity in that block not allocated to the file"],"a":3,"e":"HDFS stores the small file as one block; the block's full configured size is not reserved for the file."},{"q":"Which of the following is a common HDFS high-availability mechanism?\n\nA.","o":["Active and Standby NameNodes","Multiple Reducers only","Kafka consumer groups","Hive partitions"],"a":0,"e":"HDFS High Availability uses Active and Standby NameNodes to reduce the NameNode single point of failure."},{"q":"What is the role of a JournalNode in HDFS High Availability?\n\nA.","o":["Store application output files","Share edit-log updates between NameNodes","Run Spark executors","Process Kafka messages"],"a":1,"e":"JournalNodes provide shared edit-log storage so the Standby NameNode can stay synchronized with the Active NameNode."},{"q":"Which of the following is a typical Hive file format for analytical workloads?\n\nA.","o":["MP3","JPEG","ORC","GIF"],"a":2,"e":"ORC is a columnar storage format optimized for Hive queries, compression and predicate pushdown."},{"q":"What is predicate pushdown?\n\nA.","o":["Moving all data to the Driver","Sorting records alphabetically","Duplicating all database records","Applying filters as close to the data source as possible"],"a":3,"e":"Predicate pushdown reduces unnecessary data reading by applying filter conditions at the storage or scan level where supported."},{"q":"Which of the following is a benefit of Hive partitioning?\n\nA.","o":["Reduced data scanned for queries that filter on partition columns","Automatic removal of all duplicate records","Elimination of metadata","Guaranteed faster execution for every query"],"a":0,"e":"Partition pruning can reduce the amount of data scanned, although benefits depend on query patterns and partition design."},{"q":"Which Hive feature can improve join performance by distributing table data into a fixed number of buckets?\n\nA.","o":["Views","Bucketing","Comments","Aliases"],"a":1,"e":"Bucketing can help with certain join strategies by organizing rows according to hash values of selected columns."},{"q":"What does a Hive view generally store?\n\nA.","o":["A physical copy of all source data","HDFS block replicas","A stored query definition","Kafka consumer offsets"],"a":2,"e":"A standard Hive view stores a query definition and presents its result as a virtual table."},{"q":"Which SQL operation combines rows from two tables based on a related column?\n\nA.","o":["LIMIT","ORDER BY","DISTINCT","JOIN"],"a":3,"e":"JOIN combines rows from multiple tables based on a specified relationship or matching condition."},{"q":"What does COUNT(DISTINCT customer_id) calculate in Hive SQL?\n\nA.","o":["Number of unique non-NULL customer IDs","Total number of columns","Number of duplicate rows only","Total number of databases"],"a":0,"e":"COUNT(DISTINCT ...) counts unique non-NULL values of the specified expression."},{"q":"Which of the following is a Pig Latin command used to store a relation into a file?\n\nA.","o":["LOAD","STORE","DUMP","FILTER"],"a":1,"e":"STORE writes a Pig relation to a specified storage location."},{"q":"What is the purpose of the FOREACH ... GENERATE statement in Pig Latin?\n\nA.","o":["Delete a relation","Join two clusters","Transform or project fields from each tuple","Create a Kafka topic"],"a":2,"e":"FOREACH ... GENERATE applies expressions to records and produces a new relation."},{"q":"Which of the following is a common use of Apache Spark Streaming or Structured Streaming?\n\nA.","o":["Formatting hard disks","Creating static web pages","Managing operating system users","Processing continuous data streams"],"a":3,"e":"Spark streaming technologies process continuously arriving data using distributed computation."},{"q":"In Spark Structured Streaming, what is a micro-batch?\n\nA.","o":["A small batch of streaming data processed during a short interval","A permanent HDFS block","A Kafka broker","A Hive database"],"a":0,"e":"In micro-batch mode, Spark processes incoming streaming data in small batches at configured intervals."},{"q":"Which of the following is a common source for Spark Structured Streaming?\n\nA.","o":["Microsoft Paint","Apache Kafka","Notepad","Calculator"],"a":1,"e":"Spark Structured Streaming supports Kafka as a source for consuming event streams."},{"q":"What is the purpose of a watermark in stream processing?\n\nA.","o":["Compress every message","Change a Kafka topic name","Handle late-arriving data and manage event-time state","Increase the number of brokers"],"a":2,"e":"Watermarks help streaming engines determine how long to wait for late events and when to finalize event-time aggregations."},{"q":"Which time concept refers to when an event actually occurred?\n\nA.","o":["Processing time","Ingestion time","System time","Event time"],"a":3,"e":"Event time is the timestamp associated with the actual occurrence of an event."},{"q":"Which of the following best describes processing time?\n\nA.","o":["The time when the system processes an event","The time when the event was originally created","The time when a file was uploaded to HDFS","The time when a Kafka topic was created"],"a":0,"e":"Processing time is based on when the processing engine handles the event."},{"q":"Which consistency concept ensures that a distributed system behaves as though operations occur in a single sequential order?\n\nA.","o":["Eventual consistency","Strong consistency","Weak compression","Data partitioning"],"a":1,"e":"Strong consistency ensures that reads reflect the latest successful writes according to the system's consistency model."},{"q":"What does eventual consistency mean?\n\nA.","o":["Every replica is always immediately identical","Data is never replicated","Replicas are expected to converge if no new updates occur","Every write must fail"],"a":2,"e":"Under eventual consistency, replicas may temporarily differ but should converge after updates stop propagating."},{"q":"Which of the following is the main idea behind the CAP theorem?\n\nA.","o":["Every system must use three databases","It applies only to relational databases","It guarantees zero network failures","During a network partition, a distributed system must trade off consistency and availability"],"a":3,"e":"CAP describes the trade-off between consistency and availability when a network partition occurs."},{"q":"Which of the following is a key-value NoSQL database?\n\nA.","o":["Redis","Hive","HDFS","PostgreSQL"],"a":0,"e":"Redis is an in-memory data structure store commonly used as a key-value database."},{"q":"Which of the following is a document database?\n\nA.","o":["HDFS","MongoDB","YARN","Kafka"],"a":1,"e":"MongoDB stores documents in BSON format and supports flexible schemas."},{"q":"Which type of database is most suitable for modeling social networks with relationships between users?\n\nA.","o":["Key-value database only","Flat-file database","Graph database","Columnar file format"],"a":2,"e":"Graph databases efficiently represent entities and their relationships, making them useful for social network analysis."},{"q":"What is the main purpose of data deduplication?\n\nA.","o":["Increase the number of repeated records","Convert structured data to images","Encrypt all data","Identify and remove duplicate records"],"a":3,"e":"Deduplication reduces redundant data and can improve storage efficiency and data quality."},{"q":"Which of the following is a common challenge when processing unstructured data?\n\nA.","o":["Extracting meaningful information from varied formats","All records having identical columns","No need for preprocessing","Every file being a relational table"],"a":0,"e":"Unstructured data often requires specialized processing techniques to extract useful information."},{"q":"Which technique is commonly used to identify patterns in large datasets?\n\nA.","o":["Disk formatting","Data mining","File renaming","Screen recording"],"a":1,"e":"Data mining applies analytical methods to discover patterns, relationships and useful knowledge from datasets."},{"q":"Which of the following is a common Big Data security practice?\n\nA.","o":["Sharing passwords publicly","Disabling authentication","Encrypting sensitive data","Storing credentials in plain text"],"a":2,"e":"Encryption protects sensitive data against unauthorized access during storage and transmission."},{"q":"What is role-based access control (RBAC)?\n\nA.","o":["Giving every user administrator rights","Allowing access without authentication","Storing passwords in a database","Assigning permissions according to user roles"],"a":3,"e":"RBAC grants users permissions based on their assigned roles, helping enforce controlled access."},{"q":"Which of the following best describes a data warehouse?\n\nA.","o":["A system designed to store integrated data for reporting and analysis","A temporary file folder","A distributed operating system","A network router"],"a":0,"e":"Data warehouses integrate data from multiple sources and support reporting and analytical queries."},{"q":"What is the main difference between OLTP and OLAP?\n\nA.","o":["Both are used only for image storage","OLTP supports transactional operations, while OLAP supports analytical queries","OLAP is only for operating systems","OLTP cannot use databases"],"a":1,"e":"OLTP systems handle frequent transactions, whereas OLAP systems support complex analysis over large datasets."},{"q":"Which of the following is commonly associated with OLAP workloads?\n\nA.","o":["Frequent single-row updates only","Keyboard input processing","Complex aggregation and multidimensional analysis","Operating system booting"],"a":2,"e":"OLAP supports analytical operations such as aggregation, slicing, dicing and drill-down."},{"q":"Which of the following is a common use of machine learning with Big Data?\n\nA.","o":["Formatting spreadsheets","Renaming files","Creating folders","Predictive analytics"],"a":3,"e":"Machine learning models can analyze large datasets to identify patterns and make predictions."},{"q":"Which of the following is an example of predictive analytics?\n\nA.","o":["Forecasting customer demand using historical data","Counting the number of folders manually","Changing a database name","Copying a file between directories"],"a":0,"e":"Predictive analytics uses historical patterns and statistical or machine learning models to estimate future outcomes."},{"q":"Which of the following is a suitable approach for processing very large datasets that do not fit in the memory of a single computer?\n\nA.","o":["Manual spreadsheet editing","Distributed processing","Single-threaded local processing only","Image editing software"],"a":1,"e":"Distributed processing divides the workload among multiple machines so large datasets can be processed collectively."},{"q":"What is the purpose of a data catalog in a Big Data environment?\n\nA.","o":["Increase network bandwidth","Delete unused databases","Organize and provide information about available data assets","Execute all MapReduce tasks"],"a":2,"e":"A data catalog helps users discover datasets and understand their metadata, ownership and usage."},{"q":"Which of the following is a benefit of metadata management?\n\nA.","o":["It eliminates all data processing","It prevents data from being stored","It removes the need for data governance","It improves data discovery and understanding"],"a":3,"e":"Metadata management helps users understand data structure, origin, meaning and relationships."},{"q":"A company wants to analyze millions of website click events as they arrive. Which architecture is most appropriate?\n\nA.","o":["A streaming data pipeline using Kafka and a stream-processing engine","Manual entry into spreadsheets","A desktop word processor","A single static HTML page"],"a":0,"e":"Kafka can ingest click events, while a stream-processing engine can analyze them continuously."},{"q":"A company needs to run repeated analytical queries on large structured datasets stored in a distributed environment. Which combination is most suitable?\n\nA. P","o":["Paint and Notepad","Hive with HDFS","Photoshop and Excel only","FTP and a text editor"],"a":1,"e":"HDFS provides distributed storage, while Hive supports SQL-like analytical queries over stored datasets."}];
const bigDataTechnologiesPremiumHardQs=[{"q":"An HDFS file is 530 MB. The configured block size is 128 MB and replication factor is 3. How many physical block replicas are stored across the cluster?\n\nA.","o":["12","15","9","5"],"a":0,"e":"The file requires"},{"q":"A MapReduce job produces 800 MB of intermediate data. A Combiner reduces it to 200 MB before shuffle. What percentage reduction in intermediate data transfer is achieved?\n\nA.","o":["25%","50%","75%","80%"],"a":2,"e":"Reduction ="},{"q":"In HDFS High Availability, which mechanism prevents both NameNodes from simultaneously acting as Active?\n\nA.","o":["DataNode heartbeat","Fencing mechanism","Block replication","InputFormat"],"a":1,"e":"Fencing prevents a previously active NameNode from continuing to modify shared filesystem state after a failover."},{"q":"A MapReduce application has 100 input splits. Assuming one Mapper per split, how many Mapper tasks are initially created?\n\nA.","o":["1","10","50","100"],"a":3,"e":"In the standard MapReduce model, the number of Mapper tasks is determined by the number of input splits."},{"q":"Which statement about HDFS small files is correct?\n\nA.","o":["They can create excessive NameNode metadata overhead","They are always merged automatically","They cannot be stored in HDFS","They require one NameNode per file"],"a":0,"e":"Each file and block requires metadata, so many small files can consume substantial NameNode memory."},{"q":"A MapReduce job uses 10 reducers. Its output contains 10 reducer output files. Which statement is generally correct?\n\nA.","o":["Each file must have the same size","Each reducer writes one output file","All reducers write to the same file","Reducers cannot write output files"],"a":1,"e":"In the standard FileOutputFormat setup, each successful reducer writes its own output part file."},{"q":"Which operation is most likely to cause a shuffle in Spark?\n\nA.","o":["map()","filter()","reduceByKey()","mapPartitions()"],"a":2,"e":"reduceByKey() generally requires data with identical keys to be brought together across partitions."},{"q":"A Spark application repeatedly uses the same RDD in multiple actions. Which approach can reduce recomputation?\n\nA.","o":["Increase the number of Drivers","Disable transformations","Convert all records to strings","Cache or persist the RDD"],"a":3,"e":"Caching or persisting retains computed partitions for reuse, reducing repeated computation when the data remains available."},{"q":"Which Spark component is responsible for managing memory and CPU resources allocated to executors?\n\nA.","o":["Cluster manager","Catalyst optimizer","RDD lineage","DataFrame encoder"],"a":0,"e":"The cluster manager allocates resources to Spark applications and their executors."},{"q":"What is the primary difference between repartition() and coalesce() in Spark?\n\nA.","o":["Both always avoid shuffling","repartition() generally causes a shuffle, while coalesce() can reduce partitions without a full shuffle","coalesce() always increases partitions","repartition() works only with DataFrames"],"a":1,"e":"repartition() redistributes data through a shuffle; coalesce() can reduce partitions more efficiently when a full redistribution is unnecessary."},{"q":"A Kafka topic has 12 partitions. A consumer group has 15 active consumers. How many consumers can receive at least one partition in the same assignment?\n\nA.","o":["15","12","3","6"],"a":1,"e":"A partition can be assigned to only one consumer in a consumer group at a time. Therefore, at most 12 consumers receive partitions; three remain idle."},{"q":"In Kafka, what happens when a consumer commits an offset?\n\nA.","o":["The corresponding topic is deleted","The partition is replicated again","The broker is restarted","The consumer's progress is recorded"],"a":3,"e":"Committed offsets allow a consumer to resume reading from a known position after restarting or rebalancing."},{"q":"Which Kafka producer configuration provides the strongest acknowledgement among the following?\n\nA.","o":["acks=all","acks=0","acks=1","acks=none"],"a":0,"e":"acks=all requires acknowledgement from all in-sync replicas, subject to the topic's replication and minimum in-sync replica settings."},{"q":"A Kafka topic has a replication factor of 3 and min.insync.replicas=2. If only one replica is in sync, what happens to a producer using acks=all?\n\nA.","o":["The message is always accepted","The message is accepted with no acknowledgement","The write fails because the minimum in-sync replica requirement is not met","The topic is deleted"],"a":2,"e":"With acks=all, the broker rejects writes when the number of in-sync replicas falls below the configured minimum."},{"q":"Which statement best describes Kafka's log compaction?\n\nA.","o":["It deletes every record after one day","It retains the latest value for each key, subject to compaction rules","It compresses every message into a ZIP archive","It merges all topics into one partition"],"a":1,"e":"Log compaction preserves the latest record for each key over time, allowing Kafka to maintain a key-based state representation."},{"q":"In Hive, a table contains 1 TB of data and is partitioned by month. A query filters for one month. Which optimization is most directly useful?\n\nA.","o":["Increase the number of reducers","Disable partition columns","Convert the table into an HBase table","Partition pruning"],"a":3,"e":"Partition pruning skips unrelated month partitions and reduces the amount of data scanned."},{"q":"Which join strategy in Hive is especially suitable when one table is small enough to fit in memory and the other is large?\n\nA.","o":["Map-side join","Full outer join only","Cartesian join","Cross-cluster join"],"a":0,"e":"A map-side or map join can load the smaller table into memory and avoid a costly shuffle for suitable workloads."},{"q":"What is the primary purpose of Hive's Cost-Based Optimizer (CBO)?\n\nA.","o":["Encrypt data blocks","Create HDFS replicas","Choose efficient query execution plans using statistics","Allocate Kafka partitions"],"a":2,"e":"The CBO uses table and column statistics to evaluate alternative query plans and select a lower-cost plan."},{"q":"Which statement about Hive's ORDER BY and SORT BY is correct?\n\nA.","o":["Both always provide global ordering","ORDER BY provides global ordering, while SORT BY sorts within individual reducers","SORT BY always sorts the entire dataset globally","Neither supports sorting"],"a":1,"e":"Hive ORDER BY provides a global order, whereas SORT BY orders records within each reducer's output."},{"q":"Which HBase component stores recently written data in memory before flushing it to HFiles?\n\nA.","o":["BlockCache","WAL","ZooKeeper","MemStore"],"a":3,"e":"MemStore buffers writes in memory before flushing sorted data to HFiles in HDFS."},{"q":"What is the purpose of the HBase Write-Ahead Log (WAL)?\n\nA.","o":["Preserve updates for recovery if a RegionServer fails","Store Hive query plans","Manage Kafka offsets","Replace HDFS replication"],"a":0,"e":"WAL records updates before they are applied to MemStore, supporting recovery after failures."},{"q":"Which HBase mechanism reduces the number of HFiles by merging smaller files?\n\nA.","o":["Region splitting","Compaction","Partition pruning","Shuffle and sort"],"a":1,"e":"HBase compaction merges HFiles to improve read performance and manage storage files."},{"q":"What happens when an HBase region becomes too large?\n\nA.","o":["It is automatically deleted","Its data is converted into a Hive database","It may be split into smaller regions","The entire cluster is stopped permanently"],"a":2,"e":"Region splitting divides a large region into smaller regions to distribute data and workload."},{"q":"Which statement about HBase row keys is most important when designing a table for write-heavy workloads?\n\nA.","o":["Always use sequential timestamps at the beginning","Use identical row keys for all records","Avoid considering access patterns","Design row keys to avoid hotspotting"],"a":3,"e":"Poorly designed sequential keys can direct writes to a single region, causing hotspotting. Key design should distribute access appropriately."},{"q":"Which of the following best describes Spark lineage?\n\nA.","o":["The record of transformations used to derive an RDD","A list of Kafka brokers","A Hive table schema","An HDFS replication report"],"a":0,"e":"Lineage records the sequence of transformations that created an RDD, allowing Spark to recompute lost partitions."},{"q":"A Spark job has 8 partitions and uses reduceByKey() to produce 4 output partitions. What generally happens during execution?\n\nA.","o":["No data movement occurs","A shuffle redistributes records by key","All data moves to the Driver","The RDD is automatically deleted"],"a":1,"e":"reduceByKey() groups records with identical keys, generally requiring shuffle redistribution across partitions."},{"q":"Which Spark feature allows a failed partition to be recomputed using its dependency information?\n\nA.","o":["DataFrame schema","Broadcast variable","RDD lineage","Accumulator"],"a":2,"e":"Spark uses RDD lineage to reconstruct lost partitions by rerunning the transformations that produced them."},{"q":"A Spark application performs a large join between two DataFrames. Which technique can help avoid shuffling the large DataFrame when the other DataFrame is small?\n\nA.","o":["Checkpointing both DataFrames","Increasing driver memory only","Converting both DataFrames to strings","Broadcasting the smaller DataFrame"],"a":3,"e":"A broadcast join sends the smaller dataset to executors, allowing them to join locally with partitions of the larger dataset."},{"q":"Which Spark operation can trigger execution of previously defined lazy transformations?\n\nA.","o":["count()","map()","filter()","select()"],"a":0,"e":"count() is an action. It triggers execution of the transformations needed to calculate the result."},{"q":"What is the main purpose of a broadcast variable in Spark?\n\nA.","o":["Send a different value to every task","Efficiently distribute a read-only value to executors","Store data permanently in HDFS","Replace the Spark Driver"],"a":1,"e":"Broadcast variables distribute read-only data efficiently to worker nodes rather than repeatedly sending it with every task."},{"q":"Which Spark feature is designed to accumulate values from distributed tasks back to the Driver?\n\nA.","o":["DataFrame","RDD partition","Accumulator","Catalyst"],"a":2,"e":"Accumulators support aggregate updates from tasks, commonly for counters and diagnostic information."},{"q":"What is the main purpose of Adaptive Query Execution (AQE) in Spark SQL?\n\nA.","o":["Replace HDFS","Remove all shuffle operations","Convert every DataFrame into an RDD","Optimize the query plan using runtime statistics"],"a":3,"e":"AQE can modify execution plans at runtime based on actual data statistics, such as changing join strategies or handling skew."},{"q":"Which of the following best describes a Spark stage?\n\nA.","o":["A group of tasks separated from other stages by shuffle dependencies","A physical HDFS block","A Kafka consumer group","A Hive database"],"a":0,"e":"Spark divides jobs into stages. Shuffle boundaries generally separate stages."},{"q":"A Spark job has 10 partitions, and each partition is processed by one task in a stage. How many tasks are generated for that stage?\n\nA.","o":["1","10","20","100"],"a":1,"e":"A Spark task generally processes one partition in a stage, so 10 partitions produce 10 tasks."},{"q":"Which of the following is a likely consequence of using groupByKey() instead of reduceByKey() for aggregation?\n\nA.","o":["It always reduces network traffic","It avoids all data movement","It may transfer more intermediate data across the network","It eliminates the need for executors"],"a":2,"e":"reduceByKey() performs local aggregation before shuffling, whereas groupByKey() transfers values for grouping without that same reduction."},{"q":"In Kafka, what is the purpose of the leader replica of a partition?\n\nA.","o":["Store consumer passwords","Manage Hive metadata","Coordinate HDFS block placement","Handle reads and writes for that partition"],"a":3,"e":"The partition leader handles client requests, while follower replicas replicate its log."},{"q":"A Kafka partition has a leader and two followers. What does an In-Sync Replica (ISR) represent?\n\nA.","o":["Replicas sufficiently caught up with the leader","All consumers subscribed to the topic","All brokers in the cluster","Only offline replicas"],"a":0,"e":"ISR contains replicas considered sufficiently synchronized with the partition leader."},{"q":"Which Kafka configuration determines the minimum number of replicas that must acknowledge a write when using acks=all?\n\nA.","o":["retention.ms","min.insync.replicas","group.id","segment.bytes"],"a":1,"e":"min.insync.replicas defines the minimum ISR count required for successful writes with acks=all."},{"q":"What is a Kafka rebalance?\n\nA.","o":["Compressing all partition data","Deleting old consumer offsets","Redistributing partition assignments among consumers in a group","Merging different topics"],"a":2,"e":"A rebalance occurs when consumer group membership or partition assignments change."},{"q":"Which Kafka delivery guarantee can result in duplicate processing if a consumer processes a record but crashes before committing its offset?\n\nA.","o":["At-most-once","Exactly-once in all configurations","No delivery","At-least-once"],"a":3,"e":"The record may be read again after restart because the offset was not committed, potentially causing duplicate processing."},{"q":"Which Kafka feature helps producers avoid duplicate writes caused by retries?\n\nA.","o":["Idempotent producer","Log compaction only","Consumer auto-commit","Topic deletion"],"a":0,"e":"Kafka's idempotent producer uses producer IDs and sequence numbers to prevent duplicate log entries caused by retries."},{"q":"What is the purpose of Kafka transactions?\n\nA.","o":["Increase the number of HDFS blocks","Support atomic writes across multiple partitions and topics","Replace consumer groups","Automatically compress every topic"],"a":1,"e":"Kafka transactions allow a group of produced records to be committed atomically, supporting reliable processing patterns."},{"q":"Which statement about Kafka log retention is correct?\n\nA.","o":["All records are kept forever","Retention depends only on consumer offsets","Records can be removed according to configured time or size policies","Records are deleted immediately after consumption"],"a":2,"e":"Kafka retention policies control how long or how much data is retained, independently of whether consumers have read it."},{"q":"What is the primary function of Kafka's __consumer_offsets topic?\n\nA.","o":["Store HDFS block metadata","Store Hive schemas","Store producer passwords","Store committed consumer offsets"],"a":3,"e":"Kafka uses this internal topic to store consumer group offset information."},{"q":"A Kafka topic has 6 partitions and a replication factor of 3. How many partition replicas exist in total?\n\nA.","o":["18","9","6","3"],"a":0,"e":"Total replicas = partitions × replication factor ="},{"q":"Which statement about Kafka message ordering is correct?\n\nA.","o":["Kafka guarantees global ordering across every topic","Ordering is guaranteed within a partition","Ordering is impossible within a partition","Ordering depends only on consumer names"],"a":1,"e":"Kafka preserves record order within an individual partition, not across all partitions of a topic."},{"q":"What is the main advantage of using a stable message key in Kafka?\n\nA.","o":["It eliminates replication","It prevents all consumer failures","It can consistently route related records to the same partition","It guarantees global ordering across all partitions"],"a":2,"e":"A key-based partitioner can send records with the same key to the same partition, preserving their relative order there."},{"q":"Which Hive execution engine is commonly used for distributed processing in modern Hadoop environments?\n\nA.","o":["Photoshop","MySQL Workbench","Notepad","Tez"],"a":3,"e":"Apache Tez is a distributed data-processing framework often used as a Hive execution engine."},{"q":"What is the purpose of statistics in Hive query optimization?\n\nA.","o":["Help estimate data sizes and choose efficient execution plans","Store Kafka messages","Replicate HDFS files","Replace table schemas"],"a":0,"e":"Statistics such as row counts and column information help the optimizer choose join orders and execution strategies."},{"q":"A Hive query joins a 5 GB table with a 20 MB table. Which optimization may be appropriate if memory and configuration permit?\n\nA.","o":["Cartesian join","Map join using the smaller table","Disable all reducers permanently","Convert both tables to text files manually"],"a":1,"e":"A map join can broadcast the small table to tasks processing the larger table, avoiding a conventional reduce-side shuffle."},{"q":"What is the purpose of EXPLAIN in Hive?\n\nA.","o":["Delete a query plan","Execute a query without returning results","Display the query execution plan","Create a new database"],"a":2,"e":"EXPLAIN displays the planned execution steps and helps identify optimization opportunities."},{"q":"Which Hive operation is most likely to cause a large shuffle when joining two large tables without suitable optimizations?\n\nA.","o":["Selecting a constant","Filtering one row","Reading table metadata","Reduce-side join"],"a":3,"e":"A reduce-side join redistributes records by join key so matching records can be processed together."},{"q":"What is the main purpose of a Hive SerDe?\n\nA.","o":["Serialize and deserialize data between storage formats and Hive's internal representation","Allocate YARN containers","Replicate HDFS blocks","Manage Kafka consumer groups"],"a":0,"e":"SerDe stands for Serializer/Deserializer. It allows Hive to interpret data stored in different formats."},{"q":"Which statement about Hive managed tables is correct?\n\nA.","o":["They never store data in HDFS","Hive manages their metadata and generally their underlying data","They cannot be partitioned","They cannot be queried using HiveQL"],"a":1,"e":"Hive manages the lifecycle of managed tables, including their data in the configured warehouse location."},{"q":"What is the main purpose of dynamic partitioning in Hive?\n\nA.","o":["Create partitions only manually","Disable partition columns","Automatically create partitions based on values in input records","Convert all partitions into one file"],"a":2,"e":"Dynamic partitioning derives partition values from the input data during insertion."},{"q":"Which of the following can cause excessive small files in Hive?\n\nA.","o":["Using a single large output file","Increasing the HDFS block size","Using partition pruning","Generating many small output files across tasks or partitions"],"a":3,"e":"Excessive small files increase metadata overhead and can reduce query performance."},{"q":"Which storage format is especially suitable for Hive analytical workloads because it supports indexes and column statistics within the file?\n\nA.","o":["ORC","MP3","JPEG","Plain HTML"],"a":0,"e":"ORC is a columnar format with features such as compression, indexes and statistics that support efficient analytical reads."},{"q":"What does predicate pushdown help reduce in a columnar storage format?\n\nA.","o":["Number of database users","Unnecessary data read from storage","Number of HDFS DataNodes","Number of Hive databases"],"a":1,"e":"Filters can be applied during scanning so irrelevant row groups or data sections need not be read."},{"q":"Which of the following is a potential disadvantage of excessive Hive partitioning?\n\nA.","o":["Queries can never use partitions","HDFS stops supporting files","Too many partition directories and metadata entries","Tables cannot store strings"],"a":2,"e":"High-cardinality partition columns can create many directories and metadata overhead."},{"q":"Which statement about bucketing and partitioning in Hive is correct?\n\nA.","o":["Both always create exactly the same number of directories","Bucketing is only for text compression","Partitioning always uses a hash function","Partitioning divides data by column values, while bucketing distributes records using a hash"],"a":3,"e":"Partitioning creates logical data divisions based on column values; bucketing hashes records into a fixed number of buckets."},{"q":"In HBase, what happens when a client performs a Put operation?\n\nA.","o":["The update is recorded in the WAL and applied to MemStore","The update is written directly to the NameNode namespace","The data is sent to a Kafka consumer","The entire table is rewritten"],"a":0,"e":"HBase records the mutation in the Write-Ahead Log and updates MemStore before the data is eventually flushed to HFiles."},{"q":"What is the main purpose of HBase BlockCache?\n\nA.","o":["Store all writes permanently","Cache frequently accessed data blocks to speed up reads","Coordinate YARN applications","Manage Kafka partitions"],"a":1,"e":"BlockCache keeps frequently accessed HBase blocks in memory to reduce disk reads."},{"q":"Which HBase operation retrieves a single row using its row key?\n\nA.","o":["Scan","Flush","Get","Compact"],"a":2,"e":"Get retrieves data for a specific row key."},{"q":"Which HBase operation is generally used to retrieve a range of rows?\n\nA.","o":["Put","Delete","Flush","Scan"],"a":3,"e":"Scan reads rows across a specified range or table, optionally applying filters."},{"q":"Why is HBase often suitable for sparse datasets?\n\nA.","o":["It stores only populated cells rather than requiring every possible column value to be present","It requires every row to have identical populated columns","It stores data only as relational tuples","It cannot handle variable columns"],"a":0,"e":"HBase's flexible column-family model supports rows with different sets of populated columns."},{"q":"What is the role of HBase's Region Assignment mechanism?\n\nA.","o":["Convert HFiles into Parquet","Assign regions to RegionServers","Schedule Spark stages","Create Kafka consumer offsets"],"a":1,"e":"Region assignment distributes HBase regions among RegionServers to manage access and workload."},{"q":"What can happen if a single HBase region receives most write requests because of poor row-key design?\n\nA.","o":["Automatic global balancing is guaranteed immediately","The table becomes relational","Region hotspotting can occur","All HFiles are deleted"],"a":2,"e":"Concentrating writes on one region can overload its RegionServer and limit cluster throughput."},{"q":"What is the purpose of HBase major compaction?\n\nA.","o":["Reassign Kafka partitions","Delete the entire table","Convert the table into HiveQL","Merge HFiles and remove obsolete or deleted data versions where eligible"],"a":3,"e":"Major compaction rewrites HFiles and can remove obsolete versions and tombstoned cells according to retention rules."},{"q":"Which statement about HBase column families is correct?\n\nA.","o":["They are defined as part of the table schema","They must be created for every individual cell","They are Kafka topics","They are equivalent to HDFS DataNodes"],"a":0,"e":"Column families are declared at table creation and group related columns."},{"q":"Which of the following is a key difference between HBase and a traditional relational database?\n\nA.","o":["HBase cannot store data","HBase uses a distributed wide-column model rather than requiring conventional relational tables and joins","HBase cannot support row-level access","HBase requires every row to have exactly the same columns"],"a":1,"e":"HBase is designed for distributed, scalable wide-column storage and does not provide the same relational join model as an RDBMS."},{"q":"A Spark application has a long chain of transformations and repeatedly loses partitions. Which feature can help limit the cost of recomputation?\n\nA.","o":["Increasing the number of DataFrame columns","Removing every executor","Checkpointing","Disabling all actions"],"a":2,"e":"Checkpointing materializes an RDD to reliable storage and truncates its lineage, reducing the amount of work required for recovery."},{"q":"Which Spark storage level allows persisted data to be kept in memory and serialized?\n\nA.","o":["DISK_ONLY","NONE","MEMORY_ONLY","MEMORY_ONLY_SER"],"a":3,"e":"MEMORY_ONLY_SER stores serialized partitions in memory, which can reduce memory consumption compared with deserialized storage."},{"q":"What is the primary purpose of Spark's Tungsten execution engine?\n\nA.","o":["Improve execution efficiency through memory management and optimized processing","Replace the Kafka broker","Store HDFS metadata","Manage HBase regions"],"a":0,"e":"Tungsten focuses on improving Spark's CPU and memory efficiency through optimized execution techniques."},{"q":"A Spark job suffers from data skew during a join. Which approach can help distribute a heavily concentrated key across multiple processing tasks?\n\nA.","o":["Disable the shuffle service","Salting the join key","Remove all join conditions","Decrease the number of partitions to one"],"a":1,"e":"Salting introduces additional key values to spread records for a hot key across multiple partitions, followed by appropriate aggregation or joining."},{"q":"Which statement about Spark's coalesce(1) is correct?\n\nA.","o":["It always increases the number of partitions","It always creates a fully parallel output","It reduces the dataset to one partition, potentially limiting parallelism","It deletes all records except one"],"a":2,"e":"Coalescing to one partition can produce a single output partition, but it may create a bottleneck for large datasets."},{"q":"A Spark job processes 1 TB of data but only needs three columns from a Parquet file containing 20 columns. Which feature can reduce unnecessary data reading?\n\nA.","o":["Increasing the number of executors","Converting Parquet to CSV","Disabling column statistics","Column pruning"],"a":3,"e":"Column pruning reads only the required columns from columnar storage formats such as Parquet."},{"q":"Which Spark join strategy is generally suitable when both datasets are large and neither can be broadcast efficiently?\n\nA.","o":["Sort-merge join","Broadcast hash join","Cartesian join","Local collection join"],"a":0,"e":"Sort-merge joins are commonly used for large distributed datasets, especially when both sides are partitioned and sorted by join keys."},{"q":"What is the primary purpose of Spark's spark.sql.shuffle.partitions configuration?\n\nA.","o":["Control HDFS replication","Set the default number of partitions used for shuffle operations in Spark SQL","Set the number of Kafka brokers","Configure the number of NameNodes"],"a":1,"e":"This setting controls the default shuffle partition count for Spark SQL operations such as joins and aggregations."},{"q":"A Spark SQL query processes a highly skewed join. Which AQE capability can help improve execution?\n\nA.","o":["Automatic deletion of large tables","Replacing every executor with a Driver","Skew join optimization","Disabling all partitions"],"a":2,"e":"Adaptive Query Execution can detect skewed shuffle partitions and split them into smaller pieces for more balanced processing."},{"q":"Which of the following is the main purpose of a checkpoint in Structured Streaming?\n\nA.","o":["Increase the number of Kafka topics","Permanently store every source message in the Driver's memory","Disable fault tolerance","Store progress and state information needed for recovery"],"a":3,"e":"A streaming checkpoint stores metadata, offsets and state information required to recover a query after failure."},{"q":"What is the main difference between event-time and processing-time windows in stream processing?\n\nA.","o":["Event-time windows use when events occurred; processing-time windows use when the engine processes them","Both always produce identical results","Event-time windows ignore timestamps","Processing-time windows require HDFS replication"],"a":0,"e":"Event-time processing is based on event timestamps, while processing-time processing is based on the system's processing clock."},{"q":"A streaming system receives events out of order. Which mechanism helps determine when sufficiently late events can be ignored?\n\nA.","o":["Kafka partition count","Watermark","HDFS block size","Hive bucketing"],"a":1,"e":"A watermark establishes an event-time threshold for handling late-arriving records and managing state."},{"q":"Which of the following best describes exactly-once processing in a streaming system?\n\nA.","o":["Every event is always processed twice","Events are never stored","Each event's effect is reflected once in the supported processing and output semantics","Every event must be sent to a single machine"],"a":2,"e":"Exactly-once semantics aim to prevent lost or duplicated effects, usually through coordinated state management and transactional or idempotent sinks."},{"q":"Which technique is commonly used to make a data-processing operation safe to retry without creating duplicate effects?\n\nA.","o":["Random partitioning","Disabling acknowledgements","Removing all event identifiers","Idempotent writes"],"a":3,"e":"An idempotent operation can be repeated without changing the final result beyond the first successful execution."},{"q":"In a distributed system, what is a split-brain condition?\n\nA.","o":["Two nodes or groups incorrectly believe they are the active authority","A file is divided into HDFS blocks","A dataset is partitioned by month","A Kafka topic has multiple consumers"],"a":0,"e":"Split brain occurs when multiple nodes believe they hold active control, potentially causing conflicting writes or inconsistent state."},{"q":"Which distributed-systems mechanism helps prevent a stale leader from performing operations after leadership changes?\n\nA.","o":["Compression","Fencing token","DataFrame caching","Column pruning"],"a":1,"e":"Fencing tokens provide monotonically increasing identifiers that allow storage systems to reject operations from outdated leaders."},{"q":"According to the CAP theorem, what must a distributed system trade off during a network partition?\n\nA.","o":["Storage and computation","CPU and memory","Consistency and availability","Volume and velocity"],"a":2,"e":"During a partition, a distributed system cannot guarantee both consistency and availability in the CAP sense."},{"q":"Which statement best describes eventual consistency?\n\nA.","o":["Every read always returns the latest write immediately","Network partitions are impossible","All writes are rejected","Replicas may temporarily differ but converge when updates stop and propagation completes"],"a":3,"e":"Eventual consistency permits temporary differences between replicas while expecting convergence under suitable conditions."},{"q":"Which technique helps prevent a distributed database from losing acknowledged writes when a node fails?\n\nA.","o":["Replication with an appropriate durability and acknowledgement policy","Disabling all replicas","Storing all records only in memory","Deleting write logs immediately"],"a":0,"e":"Replication and suitable acknowledgement policies help preserve writes across failures, subject to the system's durability guarantees."},{"q":"Which of the following best describes consistent hashing?\n\nA.","o":["Sorting every database row alphabetically","Distributing keys across nodes while minimizing remapping when nodes are added or removed","Encrypting every partition key","Combining all nodes into a single server"],"a":1,"e":"Consistent hashing reduces the number of keys that need reassignment when cluster membership changes."},{"q":"A Hadoop job has 20 reducers, but one reducer takes much longer than the others because it receives most records for a particular key. What is this problem called?\n\nA.","o":["Data locality","Speculative execution","Data skew","Block replication"],"a":2,"e":"Data skew occurs when records are unevenly distributed, causing a few reducers to become bottlenecks."},{"q":"Which MapReduce feature can improve performance by processing records close to their storage location?\n\nA.","o":["Global sorting","Data duplication","Centralized execution","Data locality"],"a":3,"e":"Hadoop attempts to schedule computation near the data to reduce network transfer."},{"q":"A MapReduce job produces 100 GB of intermediate output. Which action can reduce the network traffic between Mappers and Reducers?\n\nA.","o":["Use a suitable Combiner for local aggregation","Increase the number of output files without aggregation","Disable all compression and aggregation","Move all input files to the client machine"],"a":0,"e":"A Combiner can perform local aggregation before shuffle, reducing the intermediate data transferred across the network."},{"q":"Which Hadoop component determines how input files are divided into logical input splits?\n\nA.","o":["OutputFormat","InputFormat","Reducer","Partitioner"],"a":1,"e":"InputFormat creates logical input splits and provides the mechanism for reading records from them."},{"q":"What is the purpose of a custom Partitioner in MapReduce?\n\nA.","o":["Compress input files","Manage HDFS permissions","Control which Reducer receives a particular intermediate key","Replace the Mapper"],"a":2,"e":"A Partitioner determines how intermediate keys are distributed among Reducers."},{"q":"A MapReduce application has 5 reducers. Which statement about the default HashPartitioner is correct?\n\nA.","o":["Every key goes to reducer zero","Keys are assigned randomly on every record","Reducers receive only text files","Keys are assigned using a hash-based calculation modulo the number of reducers"],"a":3,"e":"The default HashPartitioner generally uses the key's hash code and the reducer count to select a reducer."},{"q":"Which of the following is a major benefit of using Avro in distributed data pipelines?\n\nA.","o":["Schema-based serialization with support for schema evolution","Mandatory storage of all data as images","Elimination of network communication","Automatic replacement of HDFS"],"a":0,"e":"Avro supports compact serialization and schema evolution, making it useful for exchanging structured records between systems."},{"q":"Which data format is generally most suitable for analytical workloads that frequently read only selected columns from large datasets?\n\nA.","o":["Plain uncompressed text","Parquet","JPEG","MP3"],"a":1,"e":"Parquet's columnar storage enables column pruning and efficient compression for analytical queries."},{"q":"A company needs to process millions of events continuously, maintain event-time aggregations and recover state after failures. Which architecture is most appropriate?\n\nA.","o":["Manual CSV processing","A single desktop database","Kafka with a fault-tolerant stream-processing engine","A word-processing application"],"a":2,"e":"Kafka provides distributed event ingestion, while a stateful streaming engine can process events continuously and recover using checkpoints."},{"q":"A company has a large dataset in HDFS, needs interactive SQL analytics, and wants optimized columnar storage. Which combination is most suitable?\n\nA. K","o":["Kafka, Redis and JPEG","Pig, FTP and MP3","HBase, Notepad and XML","Hive with ORC or Parquet on HDFS"],"a":3,"e":"Hive supports SQL-based analytics, HDFS provides distributed storage, and ORC or Parquet provides efficient columnar storage."}];
(function(){
  const isBigDataTechnologies = () => document.getElementById("selectedModuleTitle")?.textContent.trim() === "Big Data Technologies";
  const moduleTitle = document.getElementById("selectedModuleTitle");
  const revealControls = () => { if(isBigDataTechnologies()){ document.getElementById("cppPremiumControls").hidden=false; document.getElementById("premiumUnavailable").hidden=true; } };
  new MutationObserver(revealControls).observe(moduleTitle,{childList:true,characterData:true,subtree:true});
  document.addEventListener("click",()=>setTimeout(revealControls,0));
  document.addEventListener("click",function(event){ if(event.target&&event.target.id==="openCppPremium"&&isBigDataTechnologies()){ event.preventDefault();event.stopImmediatePropagation();const level=document.getElementById("cppPremiumLevel").value;premiumQs=level==="easy"?bigDataTechnologiesPremiumEasyQs:level==="moderate"?bigDataTechnologiesPremiumModerateQs:bigDataTechnologiesPremiumHardQs;premiumIndex=0;premiumAnswers={};document.getElementById("premiumUnavailable").hidden=true;document.getElementById("premiumPracticePanel").hidden=false;renderPremium();}},true);
})();
